    grid = [row.split() for row in grid_str.strip().split('\n')]
    rows, cols = len(grid), len(grid[0])
    walls, goals, boxes, player_pos = set(), set(), set(), None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '+': walls.add((r, c))
            elif grid[r][c] == 'X': goals.add((r, c))
            elif grid[r][c] == '@': boxes.add((r, c))
            elif grid[r][c] == '$':
                boxes.add((r, c)); goals.add((r, c))
            elif grid[r][c] == '*': player_pos = (r, c)

    def get_moves(p, b):
        res = []
        q = collections.deque([(p, "")])
        v = {p}
        while q:
            (r, c), path = q.popleft()
            for dr, dc, m in [(-1,0,'U'), (1,0,'D'), (0,-1,'L'), (0,1,'R')]:
                nr, nc = r+dr, c+dc
                if (nr, nc) in walls: continue
                if (nr, nc) in b:
                    nnr, nnc = nr+dr, nc+dc
                    if (nnr, nnc) not in walls and (nnr, nnc) not in b: 
                        res.append(((nr, nc), tuple(sorted([bx if bx != (nr,nc) else (nnr,nnc) for bx in b])), path+m))
                elif (nr, nc) not in v:
                    v.add((nr, nc)); q.append(((nr, nc), path+m))
        return res

    start_boxes = tuple(sorted(list(boxes)))
    pq = [(0, player_pos, start_boxes, "")]
    visited = {(player_pos, start_boxes): 0}
    while pq:
        cost, p, b, path = heapq.heappop(pq)
        if set(b) == goals: return path
        for np, nb, mseq in get_moves(p, b):
            ncost = cost + len(mseq)
            if (np, nb) not in visited or ncost < visited[(np, nb)]:
                visited[(np, nb)] = ncost
                h = sum(min(abs(bx[0]-g[0]) + abs(bx[1]-g[1]) for g in goals) for bx in nb)
                heapq.heappush(pq, (ncost + h, np, nb, path + mseq))
    return ""

